def top_level_term_is_present(body: str, term: str) -> bool:
    if term == "Not CompletePaperSemanticKernelOnly":
        pattern = r"\bNot\s+CompletePaperSemanticKernelOnly\b"
    elif term == "paperSemanticOpenCount = 2":
        pattern = r"\bpaperSemanticOpenCount\s*=\s*2\b"
    elif term == "openSemanticTargetIds =":
        pattern = r"\bopenSemanticTargetIds\s*="
    elif term == "paperSemanticClosedCount = 3":
        pattern = r"\bpaperSemanticClosedCount\s*=\s*3\b"
    elif term == "closedSemanticTargetIds =":
        pattern = r"\bclosedSemanticTargetIds\s*="
    elif term == "openSemanticTargetClosureInputFieldOutputDetailedStatementRosterIds =":
        pattern = (
            r"\bopenSemanticTargetClosureInputFieldOutputDetailedStatementRosterIds\s*="
        )
    elif term == "openSemanticTargetClosureInputFieldOutputDetailedStatementRosters.length =":
        pattern = (
            r"\bopenSemanticTargetClosureInputFieldOutputDetailedStatementRosters"
            r"\.length\s*="
        )
    elif term == "openSemanticTargetClosureInputFieldOutputSurfaceIds =":
        pattern = r"\bopenSemanticTargetClosureInputFieldOutputSurfaceIds\s*="
    elif term == "openSemanticTargetClosureInputFieldOutputSurfaces.length =":
        pattern = (
            r"\bopenSemanticTargetClosureInputFieldOutputSurfaces"
            r"\.length\s*="
        )
    else:
        pattern = rf"\b{re.escape(term)}\b"
    return re.search(pattern, body) is not None


def top_level_current_obstruction_missing_conjuncts(text: str) -> list[str]:
    match = re.search(
        r"def\s+CompletePaperSemanticKernelOnlyCurrentObstructionCertificate\s*:\s*"
        r"Prop\s*:=\s*(.*?)\n\s*/--\s+The current paper-semantic",
        text,
        flags=re.DOTALL,
    )
    if not match:
        raise SystemExit(
            "missing CompletePaperSemanticKernelOnlyCurrentObstructionCertificate body"
        )
    body = match.group(1)
    return [
        conjunct
        for conjunct in EXPECTED_TOP_LEVEL_CURRENT_OBSTRUCTION_CONJUNCTS
        if not top_level_term_is_present(body, conjunct)
    ]


def closed_frontier_certificate_missing_conjuncts(text: str) -> list[str]:
    match = re.search(
        r"def\s+ClosedSemanticTargetsFrontierCertificate\s*:\s*"
        r"Prop\s*:=\s*(.*?)\n\s*/--\s+The closed semantic frontier",
        text,
        flags=re.DOTALL,
    )
    if not match:
        raise SystemExit("missing ClosedSemanticTargetsFrontierCertificate body")
    body = match.group(1)
    return [
        conjunct
        for conjunct in EXPECTED_CLOSED_FRONTIER_CERTIFICATE_CONJUNCTS
        if not top_level_term_is_present(body, conjunct)
    ]


def semantic_target_count_certificate_missing_conjuncts(text: str) -> list[str]:
    match = re.search(
        r"def\s+SemanticTargetCountCertificate\s*:\s*"
        r"Prop\s*:=\s*(.*?)\n\s*/--\s+The current semantic ledger count",
        text,
        flags=re.DOTALL,
    )
    if not match:
        raise SystemExit("missing SemanticTargetCountCertificate body")
    body = match.group(1)
    patterns = {
        "openSemanticTargetIds.length =": (
            r"\bopenSemanticTargetIds\.length\s*=\s*paperSemanticOpenCount\b"
        ),
        "closedSemanticTargetIds.length =": (
            r"\bclosedSemanticTargetIds\.length\s*=\s*paperSemanticClosedCount\b"
        ),
        "(semanticTargetIds semanticTargets).length =": (
            r"\(semanticTargetIds\s+semanticTargets\)\.length\s*="
            r"\s*semanticTargets\.length"
        ),
        "semanticTargets.length = paperSemanticOpenCount + paperSemanticClosedCount": (
            r"\bsemanticTargets\.length\s*=\s*paperSemanticOpenCount\s*\+\s*"
            r"paperSemanticClosedCount\b"
        ),
    }
    return [
        conjunct
        for conjunct in EXPECTED_SEMANTIC_TARGET_COUNT_CERTIFICATE_CONJUNCTS
        if re.search(patterns[conjunct], body) is None
    ]


