def paper_semantic_axiom_audit_duplicate_prints(
    axiom_audit_text: str,
) -> tuple[int, list[str]]:
    printed_decls = re.findall(
        r"^\s*#print\s+axioms\s+([A-Za-z0-9_.'α-ωΑ-Ω]+)\s*$",
        axiom_audit_text,
        flags=re.MULTILINE,
    )
    paper_semantic_decls = [
        decl
        for decl in printed_decls
        if decl.startswith("BlackwellDilemma.PaperSemanticGate.")
    ]
    counts = collections.Counter(paper_semantic_decls)
    duplicates = sorted(decl for decl, count in counts.items() if count > 1)
    return len(paper_semantic_decls), duplicates


def has_axiom_audit_print(text: str, decl: str) -> bool:
    return (
        re.search(rf"^\s*#print\s+axioms\s+{re.escape(decl)}\s*$", text, flags=re.MULTILINE)
        is not None
    )


def cross_module_certificate_references(
    text: str,
    certificate_defs: list[str],
) -> list[str]:
    paper_semantic_certificate_defs = set(certificate_defs)
    certificate_identifiers = set(CERTIFICATE_IDENTIFIER_RE.findall(text))
    return sorted(certificate_identifiers - paper_semantic_certificate_defs)


def same_base_statement_roster_certificate(
    certificate_name: str,
) -> str:
    return (
        certificate_name[: -len(CERTIFICATE_SUFFIX)]
        + STATEMENT_ROSTER_CERTIFICATE_SUFFIX
    )


def same_base_statement_roster_certificate_gap(
    text: str,
) -> tuple[list[str], list[str], list[str]]:
    certificate_defs = sorted(set(CERTIFICATE_DEF_RE.findall(text)))
    certificate_def_set = set(certificate_defs)
    non_statement_roster_defs = [
        name
        for name in certificate_defs
        if not name.endswith(STATEMENT_ROSTER_CERTIFICATE_SUFFIX)
    ]
    missing_same_base_rosters = [
        name
        for name in non_statement_roster_defs
        if same_base_statement_roster_certificate(name) not in certificate_def_set
    ]
    return certificate_defs, non_statement_roster_defs, missing_same_base_rosters


def certificate_defs_missing_theorem_targets(
    text: str,
    certificate_defs: list[str],
) -> list[str]:
    theorem_targets = set(CERTIFICATE_THEOREM_TARGET_RE.findall(text))
    return [name for name in certificate_defs if name not in theorem_targets]


def certificate_theorem_proof_names(
    text: str,
    certificate_defs: list[str],
) -> list[str]:
    certificate_def_set = set(certificate_defs)
    proof_names = {
        "".join(match.group(1).split())
        for match in CERTIFICATE_THEOREM_RE.finditer(text)
        if match.group(2) in certificate_def_set
    }
    return sorted(proof_names)


def cross_module_certificate_theorem_proof_names(
    certificate_refs: list[str],
) -> list[str]:
    certificate_ref_set = set(certificate_refs)
    proof_names: set[str] = set()
    for lean_file in sorted((ROOT / "BlackwellDilemma").glob("*.lean")):
        lean_text = read(lean_file)
        namespace = (
            "BlackwellDilemma.PaperSemanticGate"
            if lean_file.name == "PaperSemanticGate.lean"
            else "BlackwellDilemma"
        )
        for match in CERTIFICATE_THEOREM_RE.finditer(lean_text):
            if match.group(2) in certificate_ref_set:
                proof_names.add(f"{namespace}.{''.join(match.group(1).split())}")
    return sorted(proof_names)


def cross_module_certificates_missing_theorem_proofs(
    certificate_refs: list[str],
) -> list[str]:
    certificate_ref_set = set(certificate_refs)
    theorem_targets: set[str] = set()
    for lean_file in sorted((ROOT / "BlackwellDilemma").glob("*.lean")):
        lean_text = read(lean_file)
        for match in CERTIFICATE_THEOREM_RE.finditer(lean_text):
            if match.group(2) in certificate_ref_set:
                theorem_targets.add(match.group(2))
    return [decl for decl in certificate_refs if decl not in theorem_targets]


def missing_paper_semantic_axiom_audit_prints(
    axiom_audit_text: str,
    decls: list[str],
) -> list[str]:
    return [
        decl
        for decl in decls
        if not has_axiom_audit_print(
            axiom_audit_text,
            f"BlackwellDilemma.PaperSemanticGate.{decl}",
        )
    ]


def main() -> int:
    text = read(GATE)
    axiom_audit_text = read(AXIOM_AUDIT)
    lean_readme_text = read(ROOT / "README.md")
    open_ids, closed_ids = semantic_target_ids_by_status(text)
    open_count = len(open_ids)
    closed_count = len(closed_ids)
    (
        certificate_defs,
        non_statement_roster_certificate_defs,
        missing_same_base_statement_roster_defs,
    ) = same_base_statement_roster_certificate_gap(text)
    missing_certificate_theorem_targets = certificate_defs_missing_theorem_targets(
        text,
        certificate_defs,
    )
    certificate_theorem_proofs = certificate_theorem_proof_names(
        text,
        certificate_defs,
    )
    missing_certificate_def_axiom_audit_prints = (
        missing_paper_semantic_axiom_audit_prints(axiom_audit_text, certificate_defs)
    )
    missing_certificate_theorem_axiom_audit_prints = (
        missing_paper_semantic_axiom_audit_prints(
            axiom_audit_text,
            certificate_theorem_proofs,
        )
    )
    cross_module_certificate_refs = cross_module_certificate_references(
        text,
        certificate_defs,
    )
    missing_cross_module_certificate_axiom_audit_prints = [
        f"BlackwellDilemma.{decl}"
        for decl in cross_module_certificate_refs
        if not has_axiom_audit_print(axiom_audit_text, f"BlackwellDilemma.{decl}")
    ]
    cross_module_certificate_theorem_proofs = (
        cross_module_certificate_theorem_proof_names(cross_module_certificate_refs)
    )
    cross_module_certificates_missing_theorem_proofs_list = (
        cross_module_certificates_missing_theorem_proofs(cross_module_certificate_refs)
    )
    missing_cross_module_certificate_theorem_axiom_audit_prints = [
        decl
        for decl in cross_module_certificate_theorem_proofs
        if not has_axiom_audit_print(axiom_audit_text, decl)
    ]

    expected_open = theorem_count(text, "paperSemanticOpenCount_current")
    expected_closed = theorem_count(text, "paperSemanticClosedCount_current")
    expected_open_ids = theorem_id_list(text, "openSemanticTargetIds_current")
    expected_closed_ids = theorem_id_list(text, "closedSemanticTargetIds_current")
    detailed_statement_roster_ids = string_list_def(
        text, "openSemanticTargetClosureInputFieldOutputDetailedStatementRosterIds"
    )
    detailed_statement_roster_id_label_pairs = [
        (target_id, EXPECTED_OPEN_TARGET_LABELS[target_id])
        for target_id in detailed_statement_roster_ids
        if target_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    named_route_obstruction_roster_ids = string_list_def(
        text, "openSemanticTargetNamedRouteObstructionRosterIds"
    )
    named_route_obstruction_roster_id_label_pairs = [
        (target_id, EXPECTED_OPEN_TARGET_LABELS[target_id])
        for target_id in named_route_obstruction_roster_ids
        if target_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    named_frontier_certificate_roster_ids = string_list_def(
        text, "openSemanticTargetNamedFrontierCertificateRosterIds"
    )
    named_frontier_certificate_roster_id_label_pairs = [
        (target_id, EXPECTED_OPEN_TARGET_LABELS[target_id])
        for target_id in named_frontier_certificate_roster_ids
        if target_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    named_route_statement_roster_ids = string_list_def(
        text, "openSemanticTargetNamedRouteStatementRosterIds"
    )
    named_route_statement_roster_id_label_pairs = [
        (target_id, EXPECTED_OPEN_TARGET_LABELS[target_id])
        for target_id in named_route_statement_roster_ids
        if target_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    kernel_surfaces = open_kernel_surfaces(text)
    kernel_surface_ids = [surface[0] for surface in kernel_surfaces]
    kernel_surface_id_label_pairs = open_kernel_surface_id_label_pairs(text)
    kernel_surface_labels = [label for _surface_id, label in kernel_surface_id_label_pairs]
    expected_kernel_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in EXPECTED_OPEN_KERNEL_SURFACES
    ]
    expected_kernel_surface_labels = [
        label for _surface_id, label in expected_kernel_surface_id_label_pairs
    ]
    payload_surfaces = open_frontier_payload_surfaces(text)
    payload_surface_ids = [surface[0] for surface in payload_surfaces]
    payload_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in payload_surface_ids
        if surface_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    closure_input_surfaces = open_closure_input_surfaces(text)
    closure_input_surface_ids = [surface[0] for surface in closure_input_surfaces]
    closure_input_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in closure_input_surface_ids
        if surface_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    exact_closure_input_surfaces = open_exact_closure_input_surfaces(text)
    exact_closure_input_surface_ids = [
        surface[0] for surface in exact_closure_input_surfaces
    ]
    exact_closure_input_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in exact_closure_input_surface_ids
        if surface_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    closure_input_field_surfaces = open_closure_input_field_surfaces(text)
    closure_input_field_surface_ids = [
        surface[0] for surface in closure_input_field_surfaces
    ]
    closure_input_field_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in closure_input_field_surface_ids
        if surface_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    closure_input_field_output_surfaces = open_closure_input_field_output_surfaces(
        text
    )
    closure_input_field_output_surface_ids = [
        surface[0] for surface in closure_input_field_output_surfaces
    ]
    closure_input_field_output_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in closure_input_field_output_surface_ids
        if surface_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    output_equivalence_surfaces = open_output_equivalence_surfaces(text)
    output_equivalence_surface_ids = [
        surface[0] for surface in output_equivalence_surfaces
    ]
    output_equivalence_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in output_equivalence_surface_ids
        if surface_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    exact_closure_input_output_surfaces = (
        open_exact_closure_input_output_surfaces(text)
    )
    exact_closure_input_output_surface_ids = [
        surface[0] for surface in exact_closure_input_output_surfaces
    ]
    exact_closure_input_output_surface_id_label_pairs = [
        (surface_id, EXPECTED_OPEN_TARGET_LABELS[surface_id])
        for surface_id in exact_closure_input_output_surface_ids
        if surface_id in EXPECTED_OPEN_TARGET_LABELS
    ]
    obstruction_equivalence_surfaces = open_obstruction_equivalence_surfaces(text)
    obstruction_equivalence_surface_ids = [
        surface[0] for surface in obstruction_equivalence_surfaces
    ]
